package pt.realmmarriage.service;

import com.google.gson.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.util.FakePlayer;
import pt.realmmarriage.api.MarriagePermissions;
import pt.realmmarriage.block.*;
import pt.realmmarriage.compat.*;
import pt.realmmarriage.data.MarriageData;
import pt.realmmarriage.domain.MarriageLedger;
import pt.realmmarriage.domain.MarriageLedger.*;
import pt.realmmarriage.network.MarriageNetwork;
import static pt.realmmarriage.domain.MarriageLedger.require;

public final class MarriageService {
    private record Station(String dimension,BlockPos pos,long expires){}
    private static final Map<UUID,Station> STATIONS=new HashMap<>();
    private static final Map<UUID,Long> LAST=new HashMap<>(),READ_LAST=new HashMap<>(),PROPOSALS=new HashMap<>();
    private static final Map<UUID,UUID> SELECTED=new HashMap<>();
    private static final Map<UUID,Long> SCENES=new HashMap<>();
    private static boolean reported;
    private MarriageService(){}
    public static void player(ServerPlayer p){require(p!=null&&!(p instanceof FakePlayer)&&p.getServer()!=null&&p.getServer().isSameThread(),"thread");}
    public static MarriageData data(ServerPlayer p){player(p);MarriageData d=MarriageData.get(p.getServer());d.available();d.ledger.citizen(p.getUUID(),WalletBridge.name(p));return d;}
    public static boolean station(ServerPlayer p){Station s=STATIONS.get(p.getUUID());return s!=null&&System.nanoTime()<s.expires&&s.dimension.equals(p.level().dimension().location().toString())&&p.distanceToSqr(Vec3.atCenterOf(s.pos))<=64&&p.level().getBlockState(s.pos).getBlock()instanceof WeddingAltarBlock b&&b.validStructure(p.level(),s.pos);}
    private static void physical(ServerPlayer p){require(station(p),"altar");}
    public static void open(ServerPlayer p,BlockPos pos){try{data(p);pos=WeddingAltarBlock.master(p.level(),pos);STATIONS.put(p.getUUID(),new Station(p.level().dimension().location().toString(),pos,System.nanoTime()+300000000000L));physical(p);sendOpen(p);}catch(RuntimeException e){tell(p,error(e));}}
    public static void personal(ServerPlayer p){try{data(p);STATIONS.remove(p.getUUID());sendOpen(p);}catch(RuntimeException e){tell(p,error(e));}}
    public static void propose(ServerPlayer p,ServerPlayer target){player(p);require(p.isAlive()&&target.isAlive()&&p.level()==target.level()&&p.distanceToSqr(target)<=25&&p.getMainHandItem().is(BlockRegistry.ENGAGEMENT_RING.get()),"proposal");MarriageData d=data(p);long clock=d.ledger.now(System.currentTimeMillis()),last=d.ledger.citizen(p.getUUID()).lastProposalAt;require(clock-last>=30000,"cooldown");d.ledger.citizen(target.getUUID(),WalletBridge.name(target));Union u=d.ledger.propose(p.getUUID(),target.getUUID(),clock);d.ledger.citizen(p.getUUID()).lastProposalAt=clock;d.persist(p.getServer());PROPOSALS.put(p.getUUID(),clock);SELECTED.put(p.getUUID(),u.id);SELECTED.put(target.getUUID(),u.id);sendOpen(p);sendOpen(target);NotificationsBridge.send(target,"marriage.notice.proposal",WalletBridge.name(p));}
    private static Union selected(ServerPlayer p,MarriageData d){Union own=d.ledger.current(p.getUUID());UUID id=SELECTED.get(p.getUUID());Union u=id==null?null:d.ledger.unions.get(id);if(u!=null&&(u.party(p.getUUID())||p.getUUID().equals(u.priest)||u.witnesses.contains(p.getUUID())||MarriagePermissions.admin(p)&&station(p)))return u;if(own!=null)return own;return d.ledger.unions.values().stream().filter(r->r.active()&&(p.getUUID().equals(r.priest)||r.witnesses.contains(p.getUUID()))).findFirst().orElse(null);}
    public static void request(ServerPlayer p,String action,String json){
        long reply=0;try{MarriageData d=data(p);long nano=System.nanoTime();boolean read=action.equals("refresh")||action.equals("close");Long previous=(read?READ_LAST:LAST).put(p.getUUID(),nano);if(previous!=null&&nano-previous<(read?200000000L:100000000L))return;
            envelope(json);JsonObject in=JsonParser.parseString(json).getAsJsonObject();if(in.has("request")){reply=in.get("request").getAsBigDecimal().longValueExact();require(reply>0,"request");}Union u=selected(p,d);long clock=System.currentTimeMillis();
            if(!Set.of("refresh","select","objection","reason","close").contains(action))require(in.has("revision")&&in.get("revision").getAsLong()==d.ledger.revision,"stale");
            if(action.equals("close")){STATIONS.remove(p.getUUID());return;}
            switch(action){
                case "refresh"->{}
                case "select"->{UUID id=uuid(in,"union");Union target=d.ledger.union(id);require(target.party(p.getUUID())||p.getUUID().equals(target.priest)||target.witnesses.contains(p.getUUID())||MarriagePermissions.admin(p)&&station(p),"party");SELECTED.put(p.getUUID(),id);}
                case "answer"->{require(u!=null,"union");d.ledger.answer(u,p.getUUID(),in.get("accept").getAsBoolean(),clock);}
                case "configure"->{physical(p);require(u!=null,"union");List<UUID> witnesses=new ArrayList<>();for(var e:in.getAsJsonArray("witnesses")){require(witnesses.size()<2,"witnesses");witnesses.add(UUID.fromString(e.getAsString()));}Mode mode=Mode.valueOf(text(in,"mode",16));require(mode==Mode.SEPARATE||WalletBridge.loaded(),"chronicles");long fee=CrownBridge.loaded()?d.ledger.settings.fee:0;d.ledger.configure(u,p.getUUID(),uuid(in,"priest"),witnesses,mode,integer(in,"shareA",0,10000),fee,clock);}
                case "agree"->{physical(p);require(u!=null,"union");int acceptedBefore=u.plan.size();d.ledger.agree(u,p.getUUID(),clock);if(acceptedBefore<2&&u.plan.size()==2)for(UUID id:roles(u)){ServerPlayer invited=p.getServer().getPlayerList().getPlayer(id);if(invited!=null){SELECTED.put(id,u.id);sendOpen(invited);NotificationsBridge.send(invited,"marriage.notice.invitation",u.nameA+" & "+u.nameB);}}}
                case "invitation"->{require(u!=null,"union");d.ledger.invitation(u,p.getUUID(),in.get("accept").getAsBoolean(),clock);}
                case "start"->{physical(p);require(u!=null,"union");Station s=STATIONS.get(p.getUUID());require(present(p.getServer(),u,s.dimension,s.pos,d.ledger.settings,true),"presence");require(d.ledger.unions.values().stream().noneMatch(other->!other.id.equals(SELECTED.getOrDefault(p.getUUID(),d.ledger.citizen(p.getUUID()).current))&&other.ceremony()&&other.dimension.equals(s.dimension)&&other.x==s.pos.getX()&&other.y==s.pos.getY()&&other.z==s.pos.getZ()),"occupied");d.ledger.start(u,p.getUUID(),s.dimension,s.pos.getX(),s.pos.getY(),s.pos.getZ(),clock);}
                case "next"->{requireCeremony(p,u);d.ledger.next(u,p.getUUID(),clock);}
                case "objection"->{u=d.ledger.union(uuid(in,"union"));require(guest(p,u,d.ledger.settings.guestRadius),"presence");d.ledger.objection(u,p.getUUID(),clock);SELECTED.put(p.getUUID(),u.id);}
                case "reason"->{u=d.ledger.union(uuid(in,"union"));require(guest(p,u,d.ledger.settings.guestRadius),"presence");d.ledger.reason(u,p.getUUID(),text(in,"reason",256),clock);}
                case "continue"->{requireCeremony(p,u);d.ledger.continueVote(u,p.getUUID(),clock);}
                case "resume"->{requireCeremony(p,u);require(present(p.getServer(),u,u.dimension,new BlockPos(u.x,u.y,u.z),d.ledger.settings,true),"presence");d.ledger.resume(u,p.getUUID(),clock);}
                case "speaker"->{requireCeremony(p,u);require(p.getUUID().equals(u.priest)&&u.phase==Phase.SUSPENDED,"priest");u.speaker=text(in,"speaker",16);require(Set.of("objector","couple").contains(u.speaker),"phase");d.ledger.note(p.getUUID(),u,"speaker",u.speaker,clock);}
                case "ask"->{requireCeremony(p,u);d.ledger.ask(u,p.getUUID(),clock);ServerPlayer target=p.getServer().getPlayerList().getPlayer(u.vowTurn==1?u.a:u.b);if(target!=null)sendOpen(target);}
                case "vow"->{requireCeremony(p,u);d.ledger.vow(u,p.getUUID(),clock);}
                case "witness"->{requireCeremony(p,u);d.ledger.witness(u,p.getUUID(),clock);}
                case "seal"->{requireCeremony(p,u);require(present(p.getServer(),u,u.dimension,new BlockPos(u.x,u.y,u.z),d.ledger.settings,true),"presence");preflight(p.getServer(),u);d.ledger.seal(u,p.getUUID(),clock);d.persist(p.getServer());settle(p.getServer(),u);}
                case "cancel"->{require(u!=null,"union");d.ledger.cancel(u,p.getUUID(),clock);if(u.phase==Phase.COMMITTING&&u.cancelRequested){if(!u.feeAttempted)d.ledger.abortFinancial(u,clock);else d.ledger.cancelCommitted(u,p.getUUID(),clock);}}
                case "divorce"->{require(u!=null,"union");d.ledger.divorce(u,p.getUUID(),clock);}
                case "deposit","withdraw","consolidate"->{physical(p);require(u!=null,"union");money(p,u,action,action.equals("consolidate")?WalletBridge.balance(p):amount(in));}
                case "credits"->claimCredits(p,amount(in));
                case "documents"->{physical(p);require(u!=null,"union");claimDocuments(p,u);}
                case "privacy"->{d.ledger.citizen(p.getUUID()).publicSpouse=in.get("public").getAsBoolean();d.ledger.note(p.getUUID(),u,"privacy",Boolean.toString(d.ledger.citizen(p.getUUID()).publicSpouse),clock);}
                case "fee"->{physical(p);require(governor(p),"governor");long fee=amount(in);require(fee<=d.ledger.settings.feeCap&&(fee==0||CrownBridge.loaded()),"fee");CrownBridge.preflight(p.getServer(),MarriageLedger.key("fee-probe:"+UUID.randomUUID()),p.getUUID(),fee);d.ledger.settings.fee=fee;d.ledger.note(p.getUUID(),null,"wedding_fee",Long.toString(fee),clock);}
                case "settings"->{physical(p);require(MarriagePermissions.admin(p),"admin");Settings next=MarriageLedger.JSON.fromJson(in.get("settings"),Settings.class);next.validate();require(next.fee==0||CrownBridge.loaded(),"crown");d.ledger.settings=next;d.ledger.note(p.getUUID(),null,"admin_settings",MarriageLedger.JSON.toJson(next),clock);}
                case "admin_cancel"->{physical(p);require(MarriagePermissions.admin(p),"admin");Union target=d.ledger.union(uuid(in,"union"));String why=text(in,"reason",256);require(why.strip().length()>=8&&target.phase!=Phase.MARRIED,"reason");d.ledger.cancel(target,target.a,clock);if(target.phase==Phase.COMMITTING){if(!target.feeAttempted)d.ledger.abortFinancial(target,clock);else d.ledger.cancelCommitted(target,p.getUUID(),clock);}d.ledger.note(p.getUUID(),target,"admin_cancel",why,clock);}
                case "retry"->{physical(p);require(MarriagePermissions.admin(p),"admin");for(ServerPlayer online:p.getServer().getPlayerList().getPlayers())WalletJournal.recover(online);for(Union pending:d.ledger.unions.values())if(pending.phase==Phase.COMMITTING)settle(p.getServer(),pending);d.ledger.note(p.getUUID(),null,"admin_retry","Existing intents only",clock);}
                default->throw new IllegalStateException("marriage.error.request");
            }
            d.persist(p.getServer());send(p,"",reply);if(u!=null)refreshParticipants(p.getServer(),u,p.getUUID());
        }catch(RuntimeException|LinkageError failure){try{send(p,error(failure),reply);}catch(RuntimeException ignored){tell(p,error(failure));}}
    }
    private static void preflight(MinecraftServer s,Union u){var d=MarriageData.get(s);require(!d.journals.containsKey(u.a)&&!d.journals.containsKey(u.b),"pending");long total=0;for(UUID id:List.of(u.a,u.b)){ServerPlayer p=s.getPlayerList().getPlayer(id);require(p!=null,"presence");long fee=u.feePart(id);if(fee>0||u.mode==Mode.JOINT){long balance=WalletBridge.balance(p);require(balance>=fee,"funds");total=Math.addExact(total,u.mode==Mode.JOINT?balance-fee:0);}}require(total<=MarriageLedger.MAX_MONEY,"amount");CrownBridge.preflight(s,MarriageLedger.key(u.id+":wedding-fee"),u.a,u.fee);}
    public static void settle(MinecraftServer server,Union u){MarriageData d=MarriageData.get(server);d.available();require(u.phase==Phase.COMMITTING,"phase");try{
        if(u.cancelRequested&&!u.feeAttempted){d.ledger.abortFinancial(u,System.currentTimeMillis());d.persist(server);return;}
        if(!u.fundedA||!u.fundedB){if(!present(server,u,u.dimension,new BlockPos(u.x,u.y,u.z),d.ledger.settings,true))return;
            for(UUID id:List.of(u.a,u.b)){if(id.equals(u.a)?u.fundedA:u.fundedB)continue;ServerPlayer p=server.getPlayerList().getPlayer(id);WalletJournal.recover(p);if(id.equals(u.a)?u.fundedA:u.fundedB)continue;long fee=u.feePart(id),amount=u.mode==Mode.JOINT?WalletBridge.balance(p):fee;require(amount>=fee&&amount-fee<=MarriageLedger.MAX_MONEY-u.balance,"funds");UUID receipt=MarriageLedger.key(u.id+":fund:"+id);CompoundTag intent=WalletJournal.intent(p,receipt,-amount,null);Operation op=d.ledger.op(receipt,id,u,Kind.FUND,amount,fee,"",System.currentTimeMillis());WalletJournal.begin(p,op,intent);}
        }
        if(u.fundedA&&u.fundedB){if(u.fee>0&&!u.feeTransferred){u.feeAttempted=true;d.persist(server);CrownBridge.transfer(server,MarriageLedger.key(u.id+":wedding-fee"),u.a,u.fee);u.feeTransferred=true;u.feeEscrow=0;d.persist(server);}d.ledger.finish(u,System.currentTimeMillis());d.persist(server);scene(server,u,"married");for(UUID id:List.of(u.a,u.b)){ServerPlayer p=server.getPlayerList().getPlayer(id);if(p!=null)NotificationsBridge.send(p,"marriage.notice.married",u.nameA+" & "+u.nameB);}}
    }catch(RuntimeException|LinkageError failed){u.error=error(failed);d.setDirty();}}
    public static void money(ServerPlayer p,Union u,String operation,long amount){physical(p);MarriageData d=data(p);WalletJournal.recover(p);require(u.party(p.getUUID())&&u.phase==Phase.MARRIED&&u.mode!=Mode.SEPARATE&&amount>0,"funds");boolean deposit=!operation.equals("withdraw");if(deposit)require(amount<=MarriageLedger.MAX_MONEY-u.balance,"amount");else require(amount<=u.balance,"funds");UUID id=UUID.randomUUID();CompoundTag intent=WalletJournal.intent(p,id,deposit?-amount:amount,null);Operation o=d.ledger.op(id,p.getUUID(),u,deposit?Kind.DEPOSIT:Kind.WITHDRAW,amount,0,"",System.currentTimeMillis());if(!deposit)d.ledger.withdrawReserve(u,p.getUUID(),amount);WalletJournal.begin(p,o,intent);}
    public static void claimCredits(ServerPlayer p,long amount){MarriageData d=data(p);WalletJournal.recover(p);var c=d.ledger.citizen(p.getUUID());require(amount>0&&amount<=c.credit(),"funds");UUID id=UUID.randomUUID();CompoundTag intent=WalletJournal.intent(p,id,amount,null);Operation o=d.ledger.op(id,p.getUUID(),null,Kind.CREDIT,amount,0,"",System.currentTimeMillis());long left=amount;for(UUID origin:List.copyOf(c.credits.keySet())){long take=Math.min(left,c.credits.get(origin));long remain=c.credits.get(origin)-take;if(remain==0)c.credits.remove(origin);else c.credits.put(origin,remain);left-=take;if(left==0)break;}WalletJournal.begin(p,o,intent);}
    public static void claimDocuments(ServerPlayer p,Union u){physical(p);MarriageData d=data(p);WalletJournal.recover(p);require(u.party(p.getUUID())&&u.phase==Phase.MARRIED&&!u.claimed.contains(p.getUUID()),"documents");List<ItemStack> after=WalletJournal.items(p);for(boolean certificate:List.of(false,true)){int index=-1;for(int i=0;i<36;i++)if(after.get(i).isEmpty()){index=i;break;}require(index>=0,"inventory");after.set(index,documentStack(u,p.getUUID(),certificate));}UUID id=UUID.randomUUID();CompoundTag intent=WalletJournal.intent(p,id,0,after);Operation op=d.ledger.op(id,p.getUUID(),u,Kind.DOCUMENTS,0,0,"",System.currentTimeMillis());WalletJournal.begin(p,op,intent);}
    public static ItemStack documentStack(Union u,UUID owner,boolean certificate){ItemStack stack=new ItemStack(certificate?BlockRegistry.CERTIFICATE.get():BlockRegistry.WEDDING_RING.get());CompoundTag ref=new CompoundTag();ref.putUUID("union",u.id);ref.putUUID("owner",owner);ref.putUUID("token",(certificate?u.certificateTokens:u.ringTokens).get(owner));CompoundTag data=new CompoundTag();data.put("realmmarriage",ref);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));return stack;}
    public static Map<String,Object> document(ServerPlayer holder,ItemStack stack){player(holder);MarriageData d=MarriageData.get(holder.getServer());boolean certificate=stack.is(BlockRegistry.CERTIFICATE.get());require(certificate||stack.is(BlockRegistry.WEDDING_RING.get()),"documents");CompoundTag ref=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound("realmmarriage");require(ref.hasUUID("union")&&ref.hasUUID("owner")&&ref.hasUUID("token"),"forged");Union u=d.ledger.union(ref.getUUID("union"));UUID owner=ref.getUUID("owner");require(u.party(owner)&&ref.getUUID("token").equals((certificate?u.certificateTokens:u.ringTokens).get(owner)),"forged");Map<String,Object> result=new LinkedHashMap<>();result.put("authentic",true);result.put("id",u.id.toString());result.put("a",u.nameA);result.put("b",u.nameB);result.put("priest",u.priestName);result.put("witnesses",u.witnessNames.values());result.put("mode",u.mode.name());result.put("marriedAt",u.marriedAt);result.put("phase",u.phase.name());result.put("owner",owner.toString());return result;}
    public static void inspect(ServerPlayer p,InteractionHand hand){try{Map<String,Object> doc=document(p,p.getItemInHand(hand));if(p.getItemInHand(hand).is(BlockRegistry.CERTIFICATE.get())&&net.neoforged.fml.ModList.get().isLoaded("realmidentity"))try{Class.forName("pt.realmidentity.service.IdentityService").getMethod("inspectMarriageHeld",ServerPlayer.class,InteractionHand.class).invoke(null,p,hand);return;}catch(ReflectiveOperationException unavailable){/* Older optional Identity versions retain the authenticated Marriage view. */}MarriageNetwork.document(p,MarriageLedger.JSON.toJson(doc));}catch(RuntimeException e){tell(p,error(e));}}
    private static List<UUID> roles(Union u){List<UUID> list=new ArrayList<>(u.witnesses);if(u.priest!=null)list.add(u.priest);return list;}
    private static void requireCeremony(ServerPlayer p,Union u){require(u!=null&&guest(p,u,MarriageData.get(p.getServer()).ledger.settings.participantRadius),"presence");}
    public static boolean guest(ServerPlayer p,Union u,int radius){return p.isAlive()&&p.level().dimension().location().toString().equals(u.dimension)&&p.distanceToSqr(Vec3.atCenterOf(new BlockPos(u.x,u.y,u.z)))<=radius*(double)radius;}
    public static boolean present(MinecraftServer s,Union u,String dimension,BlockPos pos,Settings rules,boolean witnesses){for(UUID id:List.of(u.a,u.b,u.priest)){ServerPlayer p=s.getPlayerList().getPlayer(id);if(p==null||!p.isAlive()||!p.level().dimension().location().toString().equals(dimension)||p.distanceToSqr(Vec3.atCenterOf(pos))>rules.participantRadius*(double)rules.participantRadius)return false;}if(witnesses)for(UUID id:u.witnesses){ServerPlayer p=s.getPlayerList().getPlayer(id);if(p==null||!p.isAlive()||!p.level().dimension().location().toString().equals(dimension)||p.distanceToSqr(Vec3.atCenterOf(pos))>rules.participantRadius*(double)rules.participantRadius)return false;}return true;}
    public static boolean governor(ServerPlayer p){if(MarriagePermissions.admin(p))return true;try{var g=CouncilBridge.governor(p.getServer(),Math.max(System.currentTimeMillis(),MarriageData.get(p.getServer()).ledger.highWater));return g!=null&&g.id().equals(p.getUUID());}catch(RuntimeException|LinkageError e){return false;}}
    private static void sendOpen(ServerPlayer p){MarriageNetwork.open(p,snapshot(p,""));}
    public static void send(ServerPlayer p,String message){send(p,message,0);}
    private static void send(ServerPlayer p,String message,long reply){JsonObject view=JsonParser.parseString(snapshot(p,message)).getAsJsonObject();view.addProperty("reply",reply);MarriageNetwork.snapshot(p,MarriageLedger.JSON.toJson(view));}
    public static String snapshot(ServerPlayer p,String message){MarriageData d=data(p);Union u=selected(p,d);Map<String,Object> view=new LinkedHashMap<>();view.put("me",p.getUUID().toString());view.put("name",WalletBridge.name(p));view.put("revision",d.ledger.revision);view.put("now",Math.max(d.ledger.highWater,System.currentTimeMillis()));view.put("status",d.ledger.status(p.getUUID()));view.put("physical",station(p));view.put("admin",station(p)&&MarriagePermissions.admin(p));view.put("governor",station(p)&&governor(p));view.put("settings",d.ledger.settings);view.put("chronicles",WalletBridge.loaded());view.put("crown",CrownBridge.loaded());view.put("message",message);view.put("credits",d.ledger.citizen(p.getUUID()).credit());view.put("publicSpouse",d.ledger.citizen(p.getUUID()).publicSpouse);
        long wallet=0;try{wallet=WalletBridge.balance(p);}catch(RuntimeException ignored){}view.put("wallet",wallet);
        if(u!=null){JsonObject info=MarriageLedger.JSON.toJsonTree(u).getAsJsonObject();info.remove("ringTokens");info.remove("certificateTokens");if(!u.party(p.getUUID())){info.remove("balance");info.remove("feeEscrow");}view.put("union",info);}
        view.put("players",p.getServer().getPlayerList().getPlayers().stream().limit(128).map(other->Map.of("id",other.getUUID().toString(),"name",WalletBridge.name(other))).toList());
        view.put("invitations",d.ledger.unions.values().stream().filter(r->r.active()&&(r.party(p.getUUID())||p.getUUID().equals(r.priest)||r.witnesses.contains(p.getUUID()))).sorted(Comparator.comparingInt(r->r.party(p.getUUID())?0:r.phase==Phase.ENGAGED?1:2)).limit(12).map(r->Map.of("id",r.id.toString(),"a",r.nameA,"b",r.nameB,"phase",r.phase.name())).toList());
        view.put("history",d.ledger.audit.stream().filter(a->a.union()!=null&&d.ledger.union(a.union()).party(p.getUUID())).limit(20).toList());
        if(station(p)&&MarriagePermissions.admin(p)){view.put("audit",d.ledger.audit.stream().limit(20).toList());view.put("records",d.ledger.unions.values().stream().filter(Union::active).limit(32).map(r->Map.of("id",r.id.toString(),"a",r.nameA,"b",r.nameB,"phase",r.phase.name(),"error",r.error)).toList());view.put("errors",d.ledger.operations.values().stream().filter(o->o.state==OpState.PREPARED).limit(20).toList());}String json=MarriageLedger.JSON.toJson(view);require(json.length()<=65536,"capacity");return json;
    }
    private static void refreshParticipants(MinecraftServer server,Union u,UUID except){Set<UUID> ids=new HashSet<>(roles(u));ids.add(u.a);ids.add(u.b);for(UUID id:ids)if(!id.equals(except)){ServerPlayer target=server.getPlayerList().getPlayer(id);if(target!=null)MarriageNetwork.changed(target);}}
    public static void scene(MinecraftServer server,Union u,String kind){Map<String,Object> event=new LinkedHashMap<>();event.put("id",u.id.toString());event.put("kind",kind);event.put("a",u.nameA);event.put("b",u.nameB);event.put("objector",u.objector==null?"":MarriageData.get(server).ledger.citizen(u.objector).name);event.put("objectorId",u.objector==null?"":u.objector.toString());event.put("reason",u.reason);event.put("speaker",u.speaker);event.put("now",Math.max(System.currentTimeMillis(),MarriageData.get(server).ledger.highWater));event.put("until",u.objectionUntil);event.put("duration",MarriageData.get(server).ledger.settings.objectionSeconds);event.put("revision",u.revision);event.put("canObject",u.phase==Phase.OBJECTIONS);for(ServerPlayer p:server.getPlayerList().getPlayers())if(guest(p,u,MarriageData.get(server).ledger.settings.guestRadius)){event.put("party",u.party(p.getUUID()));MarriageNetwork.scene(p,MarriageLedger.JSON.toJson(event));}}
    public static void tick(MinecraftServer server){if(server.getTickCount()%10!=0)return;try{MarriageData d=MarriageData.get(server);d.available();long before=d.ledger.revision;d.ledger.tick(System.currentTimeMillis());for(Union u:List.copyOf(d.ledger.unions.values())){
        if(u.ceremony()&&u.phase!=Phase.SUSPENDED){var level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(u.dimension)));BlockPos pos=new BlockPos(u.x,u.y,u.z);boolean altar=level!=null&&level.hasChunkAt(pos)&&level.getBlockState(pos).getBlock()instanceof WeddingAltarBlock b&&b.validStructure(level,pos);if(!altar||!present(server,u,u.dimension,pos,d.ledger.settings,true))d.ledger.suspend(u,altar?"absence":"altar",System.currentTimeMillis());}
        if(u.phase==Phase.COMMITTING&&server.getTickCount()%100==0)settle(server,u);
        if(u.phase==Phase.CANCELLED&&u.feeAttempted&&!u.feeTransferred&&u.feeEscrow>0&&server.getTickCount()%100==0)try{CrownBridge.transfer(server,MarriageLedger.key(u.id+":wedding-fee"),u.a,u.fee);u.feeTransferred=true;u.feeEscrow=0;d.ledger.note(null,u,"cancelled_fee_settled","",System.currentTimeMillis());}catch(RuntimeException e){u.error=error(e);d.setDirty();}
        if(u.ceremony()){Long previous=SCENES.put(u.id,u.revision);if(previous==null||previous!=u.revision)scene(server,u,u.phase.name().toLowerCase(Locale.ROOT));else if(u.phase==Phase.OBJECTIONS&&server.getTickCount()%20==0)scene(server,u,"objections");}
    }if(server.getTickCount()%100==0)for(ServerPlayer p:server.getPlayerList().getPlayers())if(d.journals.containsKey(p.getUUID()))try{WalletJournal.recover(p);}catch(RuntimeException e){var op=d.ledger.operations.get(d.journals.get(p.getUUID()).getUUID("id"));op.error=error(e);d.setDirty();}if(d.ledger.revision!=before)d.persist(server);
    }catch(RuntimeException|LinkageError e){if(!reported){reported=true;org.slf4j.LoggerFactory.getLogger("RealmMarriage").error("Marriage operations paused safely",e);}}}
    public static void started(MinecraftServer server){try{MarriageData d=MarriageData.get(server);for(Union u:d.ledger.unions.values())if(u.ceremony())d.ledger.suspend(u,"restart",System.currentTimeMillis());d.persist(server);}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger("RealmMarriage").error("Marriage registry remains unavailable",e);}}
    public static void login(ServerPlayer p){try{data(p);WalletJournal.recover(p);MarriageData.get(p.getServer()).persist(p.getServer());}catch(RuntimeException e){tell(p,error(e));}}
    public static void logout(UUID id){STATIONS.remove(id);LAST.remove(id);READ_LAST.remove(id);SELECTED.remove(id);PROPOSALS.remove(id);}
    public static void clear(){STATIONS.clear();LAST.clear();READ_LAST.clear();PROPOSALS.clear();SELECTED.clear();SCENES.clear();reported=false;}
    public static String error(Throwable t){String s=Objects.toString(t.getMessage(),"");return s.startsWith("marriage.error.")?s:"marriage.error.request";}
    private static void tell(ServerPlayer p,String key){p.displayClientMessage(Component.translatable(key),false);}
    private static String text(JsonObject o,String k,int max){var v=o.get(k);require(v!=null&&v.isJsonPrimitive()&&v.getAsJsonPrimitive().isString()&&v.getAsString().length()<=max,"request");return v.getAsString();}
    private static UUID uuid(JsonObject o,String k){return UUID.fromString(text(o,k,36));}
    private static int integer(JsonObject o,String k,int min,int max){int n=o.get(k).getAsBigDecimal().intValueExact();require(n>=min&&n<=max,"request");return n;}
    private static long amount(JsonObject o){long n=o.get("amount").getAsBigDecimal().longValueExact();require(n>=0&&n<=MarriageLedger.MAX_MONEY,"amount");return n;}
    private static void envelope(String json){require(json!=null&&json.length()<=8192&&json.stripLeading().startsWith("{"),"request");int depth=0,nodes=0;boolean quoted=false,escape=false;for(char c:json.toCharArray())if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;}else if(c=='"')quoted=true;else if(c=='{'||c=='[')require(++depth<=12&&++nodes<=256,"request");else if(c=='}'||c==']')require(--depth>=0,"request");require(!quoted&&depth==0,"request");}
}
